memory_fragment = (OUT/'lignes-memoire-v1.html').read_text()
scenarios = [('Petite maison', 50, 250), ('Deux maisons réunies ×1',496,2264), ('Somme ×10',4960,22640), ('Somme ×100',49600,226400)]
def byte_label(n):
    return f'{n:,} o ({n/1024:.2f} Kio ; {n/1048576:.3f} Mio)'.replace(',', ' ')
fixed_rows=[]
expanded_rows=[]
for label, devices, points in scenarios:
    base=devices+points
    actions=points
    all_rows=base+actions
    fixed_rows.append([label,str(devices),str(points),byte_label(64*base),byte_label(96*base),str(actions),byte_label(64*all_rows),byte_label(96*all_rows)])
    common=32*points+76*all_rows+256*(points+actions)
    m64=64*all_rows+32*points+common
    m96=96*all_rows+common
    expanded_rows.append([label,str(all_rows),byte_label(64*all_rows+32*points),byte_label(m64),byte_label(m96)])
memory_fragment=memory_fragment.replace('<!-- MEMORY_TABLE -->',table(['Scénario','E','V','64 o ; A=0','96 o ; A=0','A supposé','64 o ; A=V','96 o ; A=V'],fixed_rows))
memory_fragment=memory_fragment.replace('<!-- MEMORY_EXPANDED -->',table(['Scénario','N avec A=V','64 o + Numeric32 seuls','64 o + hypothèses élargies','96 o + hypothèses élargies'],expanded_rows))
section('lignes-memoire', 'Une même ligne mémoire : valeurs, actions et équipements', memory_fragment)

section('deux-ha-reels', 'Les deux Home Assistant : inventaire exporté et coût mémoire', (OUT/'deux-ha-memoire-v1.html').read_text())

section('catalogue-banc-v2', 'Réévaluation et bancs mémoire V2', '<p>La proposition a été réexaminée avec de vrais ID dans les fiches et trois rangements à information égale. <a href="catalogue-memoire-v2.html">Lire la V2, les tests de cohérence et les mesures Linux</a>. Cette nouvelle étude distingue le catalogue partagé, les liaisons d’actions encore non résolues, les allocations mesurées et le budget du processus complet.</p>')

section('catalogue-alias-v3', 'Mémoire V3 : partager les valeurs des objets virtuels', '<p>La <a href="catalogue-memoire-v3.html">V3 conserve les lignes canoniques de 96 octets et mesure les alias partagés</a> : copies, identifiants, liens par emplacement/génération et adresses fixes. Les valeurs calculées gardent leur état autonome.</p>')

section('orientations-v4', 'Mémoire V4 : conversations, organisation et bancs séparés', '<p>La <a href="catalogue-memoire-v4.html">V4 relit les conversations fournies avec esprit critique</a>, conserve familles, maisons, étages, pièces et zones, et ajoute des bancs reproductibles pour les liens mémoire et l’association MQTT aux IDs internes. Les sources mesurées et leurs campagnes restent dans des dossiers distincts.</p>')

section('moteur-v5', 'V5 : moteur réel, transformations et fenêtres temporelles', '<p>La <a href="catalogue-memoire-v5.html">V5 ajoute la suite complète du dépôt, les chemins du vrai moteur et les codecs de valeurs/actions</a>, puis compare quatre stockages pour les moyennes sur 1 minute, 5 minutes, 1 heure et 24 heures. Les propositions restent distinguées du code livré.</p>')

section('structures-v6', 'V6 : structures mémoire et choix de stockage', '<p>La <a href="catalogue-memoire-v6.html">V6 réunit les structures champ par champ et les diagrammes mémoire</a>, avec familles, maisons, étages, pièces, zones, équipements, valeurs, actions, alias et calculs. Les mesures HA sont distinguées des budgets calculés et extrapolations jusqu’à ×1000.</p>')

