css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f4f2eb;color:#202e2b;font:16px/1.65 "Avenir Next",Verdana,sans-serif}aside{position:fixed;inset:0 auto 0 0;width:230px;padding:34px 24px;background:#163f39;color:#eff5eb;overflow:auto}aside b{font:28px Georgia,serif}aside p{font-size:12px;color:#bdd0c5}nav a{display:block;color:#e1ebe2;text-decoration:none;padding:7px 0;font-size:13px}nav a:hover,nav a:focus{color:#f9cf78;text-decoration:underline}main{margin-left:230px;max-width:1800px;padding:54px 5vw}header{padding-bottom:34px;border-bottom:2px solid #203e35}h1{font:clamp(38px,5vw,76px)/1.07 Georgia,serif;max-width:950px;margin:20px 0}h2{font:36px/1.2 Georgia,serif;margin:10px 0 24px}h3{font:24px/1.3 Georgia,serif;margin-top:34px}.eyebrow{text-transform:uppercase;font-size:11px;letter-spacing:2px;color:#557268}.badge{display:inline-block;border:1px solid #b56930;border-radius:4px;padding:4px 10px;color:#8c471e;font-size:12px}.lead{font-size:21px;max-width:950px}.stats{display:flex;gap:30px;flex-wrap:wrap;margin-top:30px}.stats b{font:37px Georgia,serif;display:block}.stats span{font-size:12px}section{padding:45px 0;border-bottom:1px solid #cbd1c5;scroll-margin-top:20px}p{max-width:1120px}a{color:#146859}code{font:12px/1.6 Menlo,Consolas,monospace;overflow-wrap:anywhere}pre{background:#193e37;color:#eff4eb;padding:24px;overflow:auto;font:13px/1.7 Menlo,monospace;border-radius:4px}.notice{border-left:4px solid #bc7433;background:#f6e9d4;padding:20px;margin:25px 0}.recommend{background:#dce9dc;padding:24px;border-left:4px solid #23684e;margin-top:25px}.flow{display:flex;align-items:stretch;gap:12px;margin:30px 0}.flow span{flex:1;background:#e1e6da;padding:20px;font-size:13px}.flow i{align-self:center}.scroll{overflow:auto;margin:20px 0}table{border-collapse:collapse;width:100%;font-size:13px;background:#fcfcf7}th{text-align:left;background:#dfe6dc;color:#233e33;font-size:11px;text-transform:uppercase;letter-spacing:.5px}th,td{padding:13px 14px;border-bottom:1px solid #dde1d6;vertical-align:top;min-width:100px}td small{color:#60746b}tbody tr:hover{background:#f0f4e9}.filter{display:block;font-size:13px;font-weight:600}input{display:block;width:min(100%,540px);font:inherit;padding:13px;border:1px solid #7c9587;background:#fff;margin-top:8px;border-radius:3px}a:focus-visible,input:focus-visible{outline:3px solid #ad682d;outline-offset:3px}[hidden]{display:none!important}footer{font-size:12px;padding-top:30px;color:#64766a}@media(max-width:950px){aside{position:static;width:auto;padding:22px}nav{display:flex;flex-wrap:wrap;gap:5px 20px}main{margin:0;padding:30px 22px}.flow{flex-direction:column}.flow i{transform:rotate(90deg)}}@media print{aside,.filter,#integration-count,#point-count{display:none}main{margin:0;padding:0}body{background:white;font-size:11px}section{break-before:auto}h2{font-size:25px}table{font-size:9px}.scroll{overflow:visible}tr{break-inside:avoid}a{color:inherit}pre{white-space:pre-wrap}.flow{display:none}}'''
js='''function bindFilter(inputId, tableId, countId){const input=document.getElementById(inputId);const rows=[...document.querySelectorAll('#'+tableId+' tbody tr')];const count=document.getElementById(countId);const normalize=s=>s.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase();function update(){const query=normalize(input.value.trim());let shown=0;for(const row of rows){row.hidden=!normalize(row.textContent).includes(query);if(!row.hidden)shown++;}count.textContent=shown+' / '+rows.length+' lignes';}input.addEventListener('input',update);update();}bindFilter('integration-filter','integration-table','integration-count');bindFilter('point-filter','point-table','point-count');'''
page='<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><title>Moli — Consolidation des entités, valeurs et actions · V1</title><style>'+css+'</style></head><body><aside><b>Moli / Analyse</b><p>Catalogue & contrats<br>Proposition V1 · 25.10.2026</p><nav aria-label="Sections">'+nav+'</nav></aside><main><header><span class="badge">PROPOSITION — NON IMPLÉMENTÉE</span><h1>Un langage commun<br>pour les données<br>de la maison.</h1><p class="lead">Entités, valeurs, fonctions et intégrations : voir les contrats existants, puis consolider leur représentation et leur stockage.</p><div class="stats">'+''.join('<div><b>'+str(n)+'</b><span>'+label+'</span></div>' for n,label in [(len(integrations),'paquets du catalogue'),(len(kinds),'variantes Kind'),(len(semantics),'sémantiques'),(len(profile_points),'points de profils statiques')])+'</div></header>'+''.join(parts)+'<footer>Document autonome · aucune requête réseau · aucune donnée de maison</footer></main><script>'+js+'</script></body></html>'
